package main
import "unsafe"
func shifted() int { a:=[3]uint32{2,3,7}; p:=unsafe.Pointer(&a[2]); return int(*(*uint32)(unsafe.Add(p,-4))) }
func window() int { a:=[3]int{2,3,7}; x:=unsafe.Slice(&a[1],2); p:=unsafe.SliceData(x[:0]); *p=5; return 10*cap(x)+a[1] }
func text() int { a:=[3]byte{3,5,7}; s:=unsafe.String(&a[1],2); n:=0; if unsafe.StringData(s)==&a[1] { n=int(s[1])+len(s) };return n }
func field() bool { var s struct{B byte; N uint32}; return uintptr(unsafe.Pointer(&s))+unsafe.Offsetof(s.N)==uintptr(unsafe.Pointer(&s.N)) }
func align() int { var x uint32; return int((uintptr(unsafe.Pointer(&x))+3)%unsafe.Alignof(x)) }
